/*
 * "NO REPLY NEEDED" (DBU-08). role:staff is checked by nodegx.security.json.
 * The message must be the newest in its conversation and the learner's own: a question that has
 * since been answered, or followed by another of hers, is refused (the page re-reads and shows the
 * newer one). Settling also marks it read. Rings a staff-only bell so every open inbox re-reads.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const id = String(Inputs.messageId || '');
    const found = id ? await q('Message', { objectId: { equalTo: id } }) : [];
    const m = found[0];
    if (!m || m.author !== m.learner) return refuse('This message could not be found. Reload the page.');
    const all = (await q('Message', { learner: { equalTo: m.learner } })).sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
    if (all[all.length - 1].objectId !== m.objectId) return refuse('Something newer has arrived in this conversation. Reload the page.');
    const now = new Date().toISOString();
    await Noodl.Records.save(m.objectId, { settledAt: m.settledAt || now, readAt: m.readAt || now }, { className: 'Message' });
    await Noodl.Records.create('Doorbell', { learner: m.learner, topic: 'inbox' }, { acl: { 'role:staff': { read: true } } });
    Outputs.done();
  } catch (e) {
    console.error('[dbu:settleQuestion]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
